"""Frozen release-specific Census definitions for SIPP income readers.

Invariants:

* Every enabled concept pins a Census name, label, type, value codes and
  ranges for its own release. No previous year's schema is a fallback.
* Ownership and time period accompany the source item. Joint shares and
  household copies retain Census's definitions; they are never reallocated.
* Missing codes are variable-specific. Unknown releases, concepts and
  categorical codes raise; ``Cannot be determined`` remains its own code.
* The embedded tables match the hashed metadata under
  ``data/external/sipp_income``. Runtime needs no metadata download.

``SippVariable.predicate_type`` records the source type verbatim. Weights
use nullable floating point when read, even where the API calls them int:
its own weight ranges and Census's CSV schemas specify decimal weights.
``allow_blank`` means a structural not-in-universe value, never no receipt.
The dictionary cover sheets distinguish numeric ``.`` and character blank;
the CSV examples use Pandas nullable types for empty fields.

The generated tables below are auditable against the committed metadata;
the concept selection and generation records live with that evidence.
"""

from __future__ import annotations

from dataclasses import dataclass

__all__ = [
    "CORE_CONCEPTS",
    "SIPP_INCOME_YEARS",
    "SippVariable",
    "income_variables",
    "replicate_variables",
    "code_label",
]

SIPP_INCOME_YEARS = tuple(range(2018, 2026))
CORE_CONCEPTS = (
    "sample_unit_id",
    "person_number",
    "panel",
    "wave",
    "month",
    "household_id_at_interview",
    "monthly_address_id",
    "weight",
)


@dataclass(frozen=True)
class SippVariable:
    """One release's verified source definition and ownership contract."""

    name: str
    label: str
    predicate_type: str
    items: tuple[tuple[str, str], ...]
    ranges: tuple[tuple[str, str, str], ...]
    ownership: str
    period: str
    source: str
    allow_blank: bool = True
    storage_type: str = ""
    domain_ranges: tuple[tuple[str, str, str], ...] = ()
    domain_source: str = ""
    structural_missing: tuple[str, ...] = ("",)


def income_variables(year: int) -> dict[str, SippVariable]:
    """Return only concepts explicitly verified for this release."""
    if type(year) is not int or year not in _RELEASES:
        raise ValueError(f"No verified SIPP income registry for {year}")
    return {
        concept: _variable(concept, definition, source)
        for concept, (definition, source) in _RELEASES[year].items()
    }


def _variable(concept: str, definition: int, source: str) -> SippVariable:
    (
        name,
        label,
        kind,
        items,
        ranges,
        storage,
        domain,
        domain_source,
        missing,
    ) = _DEFINITIONS[definition]
    ownership, period = _CONCEPTS[concept]
    return SippVariable(
        name,
        label,
        kind,
        items,
        ranges,
        ownership,
        period,
        source,
        concept not in CORE_CONCEPTS and period != "weight",
        storage,
        domain,
        domain_source,
        missing,
    )


def replicate_variables(year: int) -> dict[str, SippVariable]:
    """Verified calendar-year replicate sidecar, with its linkage columns.

    Longitudinal replicate weights are a different product and are refused.
    """
    income_variables(year)
    if year not in _REPLICATES:
        raise ValueError(f"No verified SIPP replicate layout for {year}")
    return {
        concept: _variable(concept, definition, source)
        for concept, (definition, source) in _REPLICATES[year].items()
    }


def code_label(year: int, concept: str, code: int | str) -> str:
    """Label an explicit code, refusing unverified concepts and codes."""
    table = income_variables(year)
    if concept not in table:
        raise ValueError(f"SIPP {year}: unverified concept {concept!r}")
    items = dict(table[concept].items)
    token = str(code)
    if token not in items:
        raise ValueError(f"SIPP {year} {concept}: unverified categorical code")
    return items[token]


